            # but the samples do have to have positive offset from each other,
            # so if that's not the case, we make a copy.
            if not isinstance(samples, np.ndarray):
                samples = np.asanyarray(samples)
            if samples.shape == ():
                raise TypeError("Attempted to initialize a Distribution with a scalar")
            if (
                samples.strides[-1] < samples.dtype.itemsize
                and samples.shape[-1] != 1  # strides[-1] can be 0.
            ):
                samples = samples.copy(order="C")

        if samples.shape == ():
            raise TypeError("Attempted to initialize a Distribution with a scalar")

        n_samples = samples.shape[-1]
        # For a single sample, the stride is irrelevant (and can be 0).
        if n_samples == 1:
            itemsize = samples.dtype.itemsize
        else:
            itemsize = samples.strides[-1]
        # Get the structured dtype with a single "samples" field that holds
        # a size n_samples array of "sample" fields with individual samples.
        # We need the double indirection to be able to deal with non-contiguous
        # samples (such as result from indexing a structured array).
        new_dtype = cls._get_distribution_dtype(
            samples.dtype, n_samples, itemsize=itemsize
        )
        # Create a structured array with the new dtype. We ensure we start with
        # a regular ndarray, to avoid interference between our complicated dtype
        # and something else (such as would be the case for
        # Quantity.__array_finalize__, which needs the dtype to be correct for
        # creating a StructuredUnit).
        if itemsize == samples.dtype.itemsize:
            # For contiguous last axis, a plain new view suffices.
            structured = samples.view(np.ndarray)
        else:
            # But if the last axis is not contiguous, we use __array_interface__
            # (as in np.lib.stride_tricks.as_strided) to create a new ndarray
            # where the last axis is covered by voids with size equal to the
            # stride (so that the axis becomes contiguous).
            interface = dict(samples.__array_interface__)
            interface["descr"] = [("", f"|V{itemsize}")]
            interface["typestr"] = f"|V{itemsize}"
            structured = np.asarray(DummyArray(interface, base=samples))
