    def _get_distribution_dtype(cls, dtype, n_samples, itemsize=None):
        dtype = np.dtype(dtype)
        # If not a sample dtype already, create one with a "samples" entry that
        # holds all the samples.  Here, we create an indirection via "sample"
        # because selecting an item from a structured array will necessarily
        # give non-consecutive samples, and these can only be dealt with samples
        # that are larger than a single element (plus stride tricks; see
        # __new__).  For those cases, itemsize larger than dtype.itemsize will
