    def _parse_gufunc_signature(signature):
        """Parse a gufunc signature, keeping track of optional dimensions.

        Returns lists of input and output core dimensions, with each core
        dimension given as a tuple of ``(name, optional)``.
        """
        signature = signature.replace(" ", "")
        in_sig, _, out_sig = signature.partition("->")

        def parse(sig):
            # Strip the outer parentheses, then split on the inner ones.
            parts = sig[1:-1].split("),(")
            return [
                [(dim.rstrip("?"), dim.endswith("?")) for dim in part.split(",") if dim]
                for part in parts
            ]

        return parse(in_sig), parse(out_sig)

    def __array_ufunc__(self, ufunc, method, *inputs, **kwargs):
        outputs = kwargs.pop("out", None)
        if outputs is not None and all(output is None for output in outputs):
            outputs = None

