    def _add_sample_axis(input_):
        """Get samples for a Distribution, or add a sample axis to an array."""
        # For any input that is not a Distribution, we add an axis at the
        # end, to allow proper broadcasting with the distributions.
        if isinstance(input_, Distribution):
            return input_.distribution
        if getattr(input_, "shape", ()):
            return input_[..., np.newaxis]
        return input_

    def _result_as_distribution(self, result, out):
        """Turn result into a distribution.

        If no output is given, it will create a Distribution from the array,
        If an output is given, it should be fine as is.

        Parameters
        ----------
        result : ndarray or tuple thereof
            Array(s) which need to be turned into Distribution.
        out : Distribution, tuple of Distribution or None
            Possible output |Distribution|. Should be `None` or a tuple if result
            is a tuple.

        Returns
        -------
        out : Distribution
        """
        if isinstance(result, (tuple, list)):
            if out is None:
                out = (None,) * len(result)
            # Some np.linalg functions return namedtuple, which is handy to
            # access elements by name, but cannot be directly initialized with
            # an iterator.
            result_cls = getattr(result, "_make", result.__class__)
            return result_cls(
                self._result_as_distribution(result_, out=out_)
                for (result_, out_) in zip(result, out)
            )

        if out is not None:
            # A Distribution passed in as output already holds the result.
            return out if isinstance(out, Distribution) else result

        if isinstance(result, Distribution) or not getattr(result, "shape", ()):
            return result

        return Distribution(result)
