            parts = sig[1:-1].split("),(")
            return [
                [(dim.rstrip("?"), dim.endswith("?")) for dim in part.split(",") if dim]
                for part in parts
            ]

        return parse(in_sig), parse(out_sig)

    def __array_ufunc__(self, ufunc, method, *inputs, **kwargs):
        outputs = kwargs.pop("out", None)
        if outputs is not None and all(output is None for output in outputs):
            outputs = None

        if method in {"reduce", "accumulate", "reduceat"}:
            # Axes refer to the distribution, not to the samples. If no axis
            # is given, operate over all axes of the distribution.
            ndim = np.ndim(inputs[0])
            axis = kwargs.get("axis", 0 if method == "reduceat" else None)
            if axis is None:
                axis = tuple(range(ndim))
                if method == "accumulate" and len(axis) == 1:
                    axis = axis[0]
            elif isinstance(axis, tuple):
                axis = tuple(normalize_axis_index(ax, ndim) for ax in axis)
            else:
                axis = normalize_axis_index(axis, ndim)
            kwargs["axis"] = axis
            if outputs is not None:
                kwargs["out"] = tuple(
                    output.distribution if isinstance(output, Distribution) else output
                    for output in outputs
                )
            converted = [
                input_.distribution
                if isinstance(input_, Distribution)
                else np.asanyarray(input_)[..., np.newaxis]
                if i == 0
                else input_
                for i, input_ in enumerate(inputs)
            ]
            if "where" in kwargs:
                kwargs["where"] = self._add_sample_axis(kwargs["where"])
            results = getattr(ufunc, method)(*converted, **kwargs)
            return self._result_as_distribution(
                results, out=None if outputs is None else outputs[0]
            )

        if method != "__call__" or not ufunc.signature:
            converted = [self._add_sample_axis(input_) for input_ in inputs]
            if outputs is not None:
                kwargs["out"] = tuple(
                    output.distribution if isinstance(output, Distribution) else output
                    for output in outputs
                )
            if "where" in kwargs:
                kwargs["where"] = self._add_sample_axis(kwargs["where"])
            results = getattr(ufunc, method)(*converted, **kwargs)
            if outputs is not None and ufunc.nout == 1:
                outputs = outputs[0]
            return self._result_as_distribution(results, out=outputs)

        # We're dealing with a gufunc, for which the sample axis needs to be
        # moved in front of the core dimensions.
        if "axes" in kwargs:
            raise NotImplementedError(
                "Distribution does not yet support gufunc calls with 'axes'."
            )

        if "axis" in kwargs:
            # All inputs (and outputs) have the same single core dimension,
            # which is at the location given by axis.  We keep the sample axis
            # trailing and just adjust a negative axis to skip it.
            converted = [self._add_sample_axis(input_) for input_ in inputs]
            if kwargs["axis"] < 0:
                kwargs["axis"] -= 1
            if outputs is not None:
                kwargs["out"] = tuple(
                    output.distribution if isinstance(output, Distribution) else output
                    for output in outputs
                )
            results = ufunc(*converted, **kwargs)
            if outputs is not None and ufunc.nout == 1:
                outputs = outputs[0]
            return self._result_as_distribution(results, out=outputs)

        in_sig, out_sig = self._parse_gufunc_signature(ufunc.signature)
        # Determine which optional dimensions are missing from the inputs.
        # We will insert those explicitly, and remove them from the output.
        missing = set()
        converted = []
        for input_, sig in zip(inputs, in_sig):
            ncore = len(sig)
            if isinstance(input_, Distribution):
                samples = input_.distribution
                ndim = input_.ndim
            else:
                samples = np.asanyarray(input_)
                ndim = samples.ndim
            n_present = ncore
            insert = []
            if ndim < ncore:
                optional = [i for i, (_, opt) in enumerate(sig) if opt]
                if ncore - ndim <= len(optional):
                    insert = optional[: ncore - ndim]
                    missing |= {sig[i][0] for i in insert}
                    n_present = ndim
            if isinstance(input_, Distribution):
                # Move the sample axis in front of the core dimensions.
                samples = np.moveaxis(samples, -1, samples.ndim - 1 - n_present)
            elif ndim > n_present:
                # Add a sample axis in front of the core dimensions.
                samples = np.expand_dims(samples, ndim - n_present)
            if insert:
                samples = np.expand_dims(
                    samples, tuple(i - ncore for i in insert)
                )
            converted.append(samples)

        # Determine the number of core dimensions of the outputs, and which
        # of those are to be removed.
        keepdims = kwargs.get("keepdims", False)
        out_core = []
        for sig in out_sig:
            if keepdims:
                sig = in_sig[0]
            remove = tuple(
                i - len(sig) for i, (name, _) in enumerate(sig) if name in missing
            )
            out_core.append((len(sig), remove))

        if outputs is not None:
            converted_outputs = []
            for output, (ncore, remove) in zip(outputs, out_core):
                if isinstance(output, Distribution):
                    ncore_present = ncore - len(remove)
                    output = output.distribution
                    output = np.moveaxis(output, -1, output.ndim - 1 - ncore_present)
                    if remove:
                        output = np.expand_dims(output, remove)
                elif output is not None and remove:
                    output = np.expand_dims(output, remove)
                converted_outputs.append(output)
            kwargs["out"] = tuple(converted_outputs)

        results = ufunc(*converted, **kwargs)

        if ufunc.nout == 1:
            results = (results,)
        final = []
        for i, (result, (ncore, remove)) in enumerate(zip(results, out_core)):
            output = None if outputs is None else outputs[i]
            if output is not None:
                final.append(output)
                continue
            if remove:
                result = result.squeeze(remove)
            ncore_present = ncore - len(remove)
            if result.ndim > ncore_present:
                result = np.moveaxis(result, result.ndim - 1 - ncore_present, -1)
            final.append(self._result_as_distribution(result, out=None))

        return final[0] if ufunc.nout == 1 else tuple(final)

    @staticmethod
    def _add_sample_axis(input_):
        """Get samples for a Distribution, or add a sample axis to an array."""
        # For any input that is not a Distribution, we add an axis at the
        # end, to allow proper broadcasting with the distributions.
        if isinstance(input_, Distribution):
            return input_.distribution
        if getattr(input_, "shape", ()):
            return input_[..., np.newaxis]
        return input_

    def _result_as_distribution(self, result, out):
        """Turn result into a distribution.

        If no output is given, it will create a Distribution from the array,
        If an output is given, it should be fine as is.

        Parameters
        ----------
        result : ndarray or tuple thereof
            Array(s) which need to be turned into Distribution.
        out : Distribution, tuple of Distribution or None
            Possible output |Distribution|. Should be `None` or a tuple if result
            is a tuple.

        Returns
        -------
        out : Distribution
        """
        if isinstance(result, (tuple, list)):
            if out is None:
                out = (None,) * len(result)
            # Some np.linalg functions return namedtuple, which is handy to
            # access elements by name, but cannot be directly initialized with
            # an iterator.
            result_cls = getattr(result, "_make", result.__class__)
            return result_cls(
                self._result_as_distribution(result_, out=out_)
                for (result_, out_) in zip(result, out)
            )

        if out is not None:
            # A Distribution passed in as output already holds the result.
            return out if isinstance(out, Distribution) else result

        if isinstance(result, Distribution) or not getattr(result, "shape", ()):
            return result

        return Distribution(result)
